#!/usr/bin/env bash
# Regenerates the vendored-component section of THIRD_PARTY_NOTICES.md.
#
# Every directory of third-party source in the tree must appear there with its
# licence and its copyright holders, and the licence scanner fails the build when one
# does not. Generated rather than maintained by hand: a refresh that adds or drops a
# vendored library must not depend on someone remembering to edit a list.
#
# The notices file is a legal document and is the one place permitted to name an
# upstream, which is why it is excluded from the provenance scan.
set -uo pipefail
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

NOTICES="$REPO_ROOT/THIRD_PARTY_NOTICES.md"
BEGIN="<!-- vendored:begin -->"
END="<!-- vendored:end -->"

python3 - "$REPO_ROOT" "$NOTICES" "$BEGIN" "$END" <<'PY'
import pathlib, re, sys

root, notices_path, begin, end = (
    pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]), sys.argv[3], sys.argv[4]
)

LICENCE_NAMES = [
    ("0BSD", r"BSD Zero Clause License"),
    ("Unlicense", r"free and unencumbered software released into the public domain"),
    ("Apache-2.0", r"Apache License"),
    ("MIT", r"\bMIT License\b|Permission is hereby granted, free of charge"),
    ("ISC", r"\bISC License\b"),
    ("BSD-3-Clause", r"Redistributions in binary form.*?name of the copyright holder"),
    ("BSD-2-Clause", r"Redistributions in binary form"),
    ("Zlib", r"zlib License|altered source versions must be plainly marked"),
]

def licence_file(directory: pathlib.Path):
    candidates = [
        e for e in sorted(directory.iterdir())
        if e.is_file() and e.name.upper().startswith(("LICENSE", "COPYING", "NOTICE"))
    ]
    for prefix in ("LICENSE", "COPYING", "NOTICE"):
        for entry in candidates:
            if entry.name.upper().startswith(prefix):
                return entry
    return None

def describe(path: pathlib.Path):
    text = path.read_text(encoding="utf-8", errors="replace")
    kind = "see the licence file"
    for name, pattern in LICENCE_NAMES:
        if re.search(pattern, text, re.I | re.S):
            kind = name
            break
    # An actual copyright statement names a year and a holder. The licence body
    # says "copyright" several times over without being one, and listing those
    # lines as holders would make this document wrong as well as untidy.
    statement = re.compile(
        r"copyright\s*(?:\(c\)|©|\(C\))?\s*(?:\d{4}(?:\s*[-,]\s*\d{4})*)\s+\S",
        re.I,
    )
    holders = []
    for line in text.splitlines():
        cleaned = re.sub(r"^[\s*#/]+", "", line).strip().rstrip(".")
        if not cleaned or not statement.search(cleaned) or len(cleaned) > 160:
            continue
        if cleaned not in holders:
            holders.append(cleaned)
        if len(holders) >= 3:
            break
    return kind, holders

rows = []
# The engine itself, then each vendored library, then the grammars.
engine_licence = root / "engine" / "LICENSE-ENGINE"
if engine_licence.is_file():
    kind, holders = describe(engine_licence)
    rows.append(("engine/", "Extraction and typed-resolution engine", kind,
                 holders, "engine/LICENSE-ENGINE"))

for directory in sorted((root / "engine" / "vendored").glob("*")):
    if not directory.is_dir():
        continue
    lf = licence_file(directory)
    if lf is None:
        continue
    kind, holders = describe(lf)
    rel = directory.relative_to(root).as_posix()
    rows.append((f"{rel}/", f"Vendored library: {directory.name}", kind, holders,
                 lf.relative_to(root).as_posix()))

grammar_rows = []
for directory in sorted((root / "engine" / "grammars").glob("*")):
    if not directory.is_dir():
        continue
    lf = licence_file(directory)
    if lf is None:
        continue
    kind, holders = describe(lf)
    grammar_rows.append((directory.name, kind, holders[0] if holders else "",
                         lf.relative_to(root).as_posix()))

out = [begin, "",
       "## Vendored components",
       "",
       "Third-party source copied into this repository. Each directory carries its own",
       "licence file at the path given, unchanged, and that file governs the code in it.",
       "This section is generated by `scripts/vendor/notices-update.sh`.",
       ""]
for path, what, kind, holders, licence_at in rows:
    out.append(f"### `{path}`")
    out.append("")
    out.append(f"- **What**: {what}")
    out.append(f"- **Licence**: {kind}")
    if holders:
        out.append("- **Copyright**: " + "; ".join(holders))
    out.append(f"- **Licence text**: `{licence_at}`")
    out.append("")

out.append("### `engine/grammars/`")
out.append("")
out.append("Parser tables, one directory per language. Each carries its own licence file.")
out.append("")
out.append("| Language | Licence | Copyright | Licence text |")
out.append("|---|---|---|---|")
for name, kind, holder, licence_at in grammar_rows:
    out.append(f"| `{name}` | {kind} | {holder} | `{licence_at}` |")
out.append("")
out.append(end)

text = notices_path.read_text()
block = "\n".join(out)
if begin in text and end in text:
    text = re.sub(re.escape(begin) + r".*?" + re.escape(end), block, text, flags=re.S)
else:
    text = text.rstrip() + "\n\n" + block + "\n"
notices_path.write_text(text)
print(f"components listed: {len(rows)} directories plus {len(grammar_rows)} grammars")
PY
